import{_ as n,o as s,c as e,ai as p}from"./chunks/framework.XEs52zTF.js";const b=JSON.parse('{"title":"进入 SSA 世界","description":"","frontmatter":{"title":"进入 SSA 世界","chapterId":"chapter15","prev":{"text":"数据流分析","link":"/chapter14"},"next":{"text":"优化必须保持语义","link":"/chapter16"}},"headers":[],"relativePath":"chapter15.md","filePath":"chapter15.md"}'),i={name:"chapter15.md"};function l(t,a,r,o,c,d){return s(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="_15-ssa、支配关系与-φ-一个名字只定义一次" tabindex="-1">15 SSA、支配关系与 φ：一个名字只定义一次 <a class="header-anchor" href="#_15-ssa、支配关系与-φ-一个名字只定义一次" aria-label="Permalink to &quot;15 SSA、支配关系与 φ：一个名字只定义一次&quot;">​</a></h1><h2 id="学习目标与边界" tabindex="-1">学习目标与边界 <a class="header-anchor" href="#学习目标与边界" aria-label="Permalink to &quot;学习目标与边界&quot;">​</a></h2><p>本章是扩展路线，主线编译器没有现成的 SSA 命令。先会 CFG、前驱后继和集合迭代。目标是手算支配集合，在分支与循环中放置 φ，理解重命名栈，以及为什么离开 SSA 时需要并行复制。</p><p>SSA 是 Static Single Assignment，即静态单赋值。每个名字在程序文本中只定义一次；这不意味着循环指令运行时只执行一次，也不意味着源语言变量不能赋值。编译器为每次静态定义分配不同的 IR 名字。</p><h2 id="先处理直线代码" tabindex="-1">先处理直线代码 <a class="header-anchor" href="#先处理直线代码" aria-label="Permalink to &quot;先处理直线代码&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>源级赋值          SSA 名字</span></span>
<span class="line"><span>x = 3             x0 = 3</span></span>
<span class="line"><span>x = x + 1         x1 = add x0, 1</span></span>
<span class="line"><span>print x           print x1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>读 x1 时无需追问此前哪个分支最后写过 x：定义直接指向 <code>add x0,1</code>。值的使用表也更容易维护。给同一变量所有出现简单加一个固定后缀不行；新名字对应的是定义，不是源码里的拼写。</p><h2 id="分支汇合为什么需要-φ" tabindex="-1">分支汇合为什么需要 φ <a class="header-anchor" href="#分支汇合为什么需要-φ" aria-label="Permalink to &quot;分支汇合为什么需要 φ&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>entry: branch cond, left, right</span></span>
<span class="line"><span>left:  x1 = 4; jump join</span></span>
<span class="line"><span>right: x2 = 6; jump join</span></span>
<span class="line"><span>join:  x3 = phi [x1,left], [x2,right]</span></span>
<span class="line"><span>       print x3</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>φ 的意思是“根据刚刚从哪条前驱边进入，选择对应的值”。它不是先算两个参数再比较大小，也不是运行时调用名叫 phi 的函数。如果从 left 过来，x3=4；从 right 过来，x3=6。值与前驱必须成对记录，不能靠数组顺序暗中约定。</p><p>在这张菱形图中，left 不在所有到 join 的路径上，因此 left 的定义不能直接作为 join 中唯一可用的 x。φ 把这个路径差异显式放到一个新定义中。</p><h2 id="支配-所有进入路径都经过谁" tabindex="-1">支配：所有进入路径都经过谁 <a class="header-anchor" href="#支配-所有进入路径都经过谁" aria-label="Permalink to &quot;支配：所有进入路径都经过谁&quot;">​</a></h2><p>若从入口到 B 的每条路径都经过 A，称 A 支配 B。每块支配自己，入口支配所有可达块。对可达图，可用集合迭代求解：入口的集合只有自己，其他块先初始化为全部可达块，再反复计算。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dom(entry) = {entry}</span></span>
<span class="line"><span>Dom(B) = {B} ∪ intersection(Dom(P))，P 为 B 的前驱</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>菱形图中 Dom(left)={entry,left}，Dom(right)={entry,right}，Dom(join)={entry,join}。这里合并用交集，因为要“每条路径都经过”；第 14 章活跃分析用并集，因为问“存在一条路径会读取”。量词不同，集合操作也不同。</p><p>直接支配者 idom(B) 是最接近 B 的严格支配者。把它们连起来形成支配树，菱形图中 left、right、join 的 idom 都是 entry。不可达块需要先过滤或单独定义策略，否则空前驱的交集会产生误导。</p><h2 id="支配边界与-φ-放置" tabindex="-1">支配边界与 φ 放置 <a class="header-anchor" href="#支配边界与-φ-放置" aria-label="Permalink to &quot;支配边界与 φ 放置&quot;">​</a></h2><p>A 的支配边界包含这些块 Y：A 支配 Y 的某个前驱，却不严格支配 Y。直觉上，这是“A 所控制的定义和其他路径第一次汇合”的地方。菱形图中 join 属于 left 与 right 的支配边界。</p><p>经典构造方法是：对一个源变量，收集它所有定义块；在这些块的支配边界插 φ；新插入的 φ 也算定义，必要时继续沿边界传播。这样得到迭代支配边界。第一版可以在所有可能汇合处放较多 φ，再删除无用者；改进版本结合活跃性，只放在该变量活跃的地方，得到剪枝 SSA。</p><p>不要在“每个有两条前驱的块”为“每个变量”都无条件放 φ。这样可能仍能表达程序，但会膨胀并掩盖构造思路；更危险的是放了 φ 却没有为每条前驱提供正确输入。</p><h2 id="重命名栈-沿支配树遍历" tabindex="-1">重命名栈：沿支配树遍历 <a class="header-anchor" href="#重命名栈-沿支配树遍历" aria-label="Permalink to &quot;重命名栈：沿支配树遍历&quot;">​</a></h2><p>为每个源变量维护一个栈。遇到定义就产生新版本并压栈，遇到读取就取栈顶。遍历块时先处理本块 φ 定义，再处理普通指令；然后为每个后继的 φ 填上当前边应传出的版本。递归处理支配树子节点后，弹出本块新增的定义。</p><p>这不是沿 CFG 任意深度优先遍历，因为 CFG 可能有回边。支配树无环，栈的进出正好反映哪些定义支配当前使用。对块内普通使用，还需要定义在该使用之前；仅有块级支配不够。</p><h2 id="循环例子-φ-可以引用稍后定义" tabindex="-1">循环例子：φ 可以引用稍后定义 <a class="header-anchor" href="#循环例子-φ-可以引用稍后定义" aria-label="Permalink to &quot;循环例子：φ 可以引用稍后定义&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>entry:</span></span>
<span class="line"><span>    jump loop</span></span>
<span class="line"><span>loop:</span></span>
<span class="line"><span>    i0 = phi [0,entry], [i1,body]</span></span>
<span class="line"><span>    c = lt i0, 3</span></span>
<span class="line"><span>    branch c, body, exit</span></span>
<span class="line"><span>body:</span></span>
<span class="line"><span>    print i0</span></span>
<span class="line"><span>    i1 = add i0, 1</span></span>
<span class="line"><span>    jump loop</span></span>
<span class="line"><span>exit:</span></span>
<span class="line"><span>    return 0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>第一次从 entry 进入时 i0=0；之后从 body 返回，i0 取上一轮 i1。静态只有一个 i1 定义，但运行时会重复执行。φ 输入的使用位置应理解为对应前驱边，而非简单的文本先后，所以回边上的 i1 合法。</p><h2 id="离开-ssa-并行复制与关键边" tabindex="-1">离开 SSA：并行复制与关键边 <a class="header-anchor" href="#离开-ssa-并行复制与关键边" aria-label="Permalink to &quot;离开 SSA：并行复制与关键边&quot;">​</a></h2><p>对每个 φ，把相应输入复制放在对应前驱边上，再移除 φ。若有多个 φ，这组复制是同时发生的。<code>a←b, b←a</code> 不能顺序执行为 a=b; b=a，因为第二步会读到被覆盖的值；必须使用临时变量或更一般的并行复制调度算法。</p><p>关键边是源块有多个后继、目标块有多个前驱的边。复制不能直接塞到源块末尾，否则其他后继也会执行；也不能塞到目标块开头，否则其他前驱也会执行。先拆一块专门代表这条边，再把复制放进去。</p><h2 id="实验、常见错误与验收" tabindex="-1">实验、常见错误与验收 <a class="header-anchor" href="#实验、常见错误与验收" aria-label="Permalink to &quot;实验、常见错误与验收&quot;">​</a></h2><p>先手工构造菱形图，分别从左右路径执行 φ；再构造计数循环，执行三轮。实现验证器时检查每个值唯一定义、普通使用被定义支配、φ 输入块与实际前驱相符，以及同块指令顺序。</p><p>练习：给循环增加 sum 的累加，写出两个 φ；再展示交换 a、b 所需的临时复制。</p><details><summary>参考答案</summary><p>sum0=phi [0,entry],[sum1,body]，body 中 sum1=add sum0,i0。输出 sum 时必须读取退出路径对应的最新版本。交换需要 tmp=b; b=a; a=tmp，或等价的循环分解。验收不只看结果，还要故意删掉一条 φ 前驱，确认验证器能拒绝坏 IR。</p></details><h2 id="来源与后续" tabindex="-1">来源与后续 <a class="header-anchor" href="#来源与后续" aria-label="Permalink to &quot;来源与后续&quot;">​</a></h2><p>已阅读本地 <code>compilers-papers-we-love/ir/TOPLAS1991 Efficiently Computing Static Single Assignment Form and the Control Dependence Graph.pdf</code> 第 1—3 页的表示、分支与 φ 示例，算法细节可继续精读原论文；<a href="https://llvm.org/docs/LangRef.html#phi-instruction" target="_blank" rel="noreferrer">LLVM φ 指令定义</a> 给出该系统的具体约束。下一章用这些显式依赖组织安全优化。</p>`,35)])])}const u=n(i,[["render",l]]);export{b as __pageData,u as default};
